-- All rows, accounts, source nodes and requests below are synthetic.
CREATE OR REPLACE FUNCTION public.s2_fixture_assert(p_ok boolean,p_label text) RETURNS text LANGUAGE plpgsql AS $$ BEGIN IF p_ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL:%',p_label; END IF; RETURN 'PASS:'||p_label; END $$;
SET ROLE anon;
SELECT s2_fixture_assert((SELECT array_agg(id ORDER BY id) FROM posts)=ARRAY[1,2,5,6,7]::bigint[],'anon direct table: public/forum/null tags preserved; both drafts excluded');
SELECT s2_fixture_assert((SELECT count(*) FROM redirect_map)=5,'view owner cannot expose draft identity');
SELECT s2_fixture_assert(chat_search_facts('בדיקה',5) NOT LIKE '%SECRET%','chat facts cannot expose draft title/excerpt/content');
SELECT s2_fixture_assert((SELECT count(*) FROM cross_source_posts(ARRAY['בדיקה']))=1 AND (SELECT bool_and(wp_id=101 AND via='graph') FROM cross_source_posts(ARRAY['בדיקה'])),'graph exact WP/slug identity only; missing/private/mismatched rows excluded');
SELECT s2_fixture_assert((SELECT count(*) FROM hot_posts_live(7,100))=5 AND (SELECT bool_and(title NOT LIKE '%SECRET%') FROM hot_posts_live(7,100)),'hot posts remain public without draft title/image');
SELECT s2_fixture_assert((name_lab_research('בדיקה',0)->>'posts_count')::int=5 AND name_lab_research('בדיקה',0)::text NOT LIKE '%SECRET%','name-lab list and total share draft boundary');
SELECT s2_fixture_assert(jsonb_array_length(number_dossier_json(1820)->'posts')=2 AND number_dossier_json(1820)::text NOT LIKE '%SECRET%' AND (number_dossier_json(1820)->>'value')::int=1820,'number dossier keeps public source titles and numeric value; no draft title');
SELECT s2_fixture_assert((SELECT count(*) FROM post_conversation_projection(103,200))=0 AND (SELECT count(*) FROM post_conversation_projection(104,200))=0,'unpublished parent cannot expose public child conversation');
SELECT s2_fixture_assert((SELECT count(*) FROM post_conversation_projection(101,200))=1 AND (SELECT count(*) FROM post_conversation_projection(102,200))=1,'published normal and Forum comments preserved');
SELECT s2_fixture_assert((SELECT count(*) FROM lang_links_list(NULL))=1 AND (SELECT count(*) FROM lang_links_list('visitor-known-A'))=1 AND (SELECT count(*) FROM lang_links_list(''))=1,'unverified visitor strings never select pending/rejected links');
SELECT s2_fixture_assert((SELECT bool_and(created_by_visitor IS NULL AND reviewed_by IS NULL AND created_by_name='קרדיט ציבורי') FROM lang_links_list('visitor-known-A')),'public attribution retained; visitor/reviewer identifiers redacted');
SELECT s2_fixture_assert(NOT has_table_privilege('anon','language_links','SELECT') AND NOT has_function_privilege('anon','lang_links_pending()','EXECUTE'),'anonymous direct private links and admin pending RPC remain denied');
RESET ROLE;
SET ROLE authenticated;
SET request.jwt.claim.sub='00000000-0000-4000-8000-000000000002';
SELECT s2_fixture_assert((SELECT count(*) FROM posts)=5,'regular verified user has no draft exception');
SELECT s2_fixture_assert((SELECT count(*) FROM lang_links_list('visitor-known-A'))=1 AND (SELECT count(*) FROM lang_links_pending())=0,'ordinary account cannot claim unverified pending identity');
DO $$ BEGIN BEGIN INSERT INTO public.posts(id,title,tags) VALUES(99,'UNAUTHORIZED',ARRAY['טיוטה']); RAISE EXCEPTION 'FAIL:ordinary write admitted'; EXCEPTION WHEN insufficient_privilege THEN NULL; END; END $$;
SELECT s2_fixture_assert(lang_link_review('00000000-0000-4000-8000-000000000022','approve')='forbidden','ordinary account cannot approve pending link');
SET request.jwt.claim.sub='00000000-0000-4000-8000-000000000003';
SELECT s2_fixture_assert((SELECT count(*) FROM lang_links_list('visitor-known-A'))=1,'second account does not gain pending rows');
SET request.jwt.claim.sub='00000000-0000-4000-8000-000000000001';
SELECT s2_fixture_assert((SELECT count(*) FROM posts)=7,'verified admin retains draft access');
UPDATE posts SET excerpt='ADMIN_EDIT_PRESERVED' WHERE id=3;
SELECT s2_fixture_assert((SELECT excerpt FROM posts WHERE id=3)='ADMIN_EDIT_PRESERVED','admin draft editing remains authorized');
SELECT s2_fixture_assert((SELECT count(*) FROM lang_links_pending())=1,'verified admin retains separate pending review');
RESET ROLE;
BEGIN;
UPDATE posts SET tags=ARRAY['טיוטה'] WHERE id=1;
SET LOCAL ROLE anon;
SELECT s2_fixture_assert((SELECT bool_and(via='text' AND title NOT LIKE '%SECRET%' AND wp_id<>101) FROM cross_source_posts(ARRAY['בדיקה'])),'withdrawn graph source cannot retain metadata; admitted text fallback survives');
RESET ROLE;
ROLLBACK;
-- No public/private storage row was changed by any list/read function above.
SELECT s2_fixture_assert((SELECT count(*) FROM language_links)=3 AND (SELECT count(*) FROM language_links WHERE status='approved')=1,'read paths did not auto-approve, delete, follow or send');
SELECT s2_fixture_assert((SELECT role FROM users WHERE id='00000000-0000-4000-8000-000000000001')='admin','admin role unchanged');
